ALTER TABLE public.posts ADD COLUMN area_scope text NOT NULL DEFAULT 'local', ADD COLUMN district text NOT NULL DEFAULT '', ADD COLUMN state text NOT NULL DEFAULT '', ADD COLUMN service_type text NOT NULL DEFAULT '', ADD COLUMN public_photo text NOT NULL DEFAULT '', ADD COLUMN public_brand text NOT NULL DEFAULT '';
ALTER TABLE public.posts ADD CONSTRAINT posts_area_scope_check CHECK (area_scope IN ('local','district','state','country'));
ALTER TABLE public.profiles ADD COLUMN public_photo text NOT NULL DEFAULT '', ADD COLUMN public_brand text NOT NULL DEFAULT '', ADD COLUMN show_public boolean NOT NULL DEFAULT false;
CREATE TABLE public.membership_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, transaction_id text NOT NULL UNIQUE, amount integer NOT NULL DEFAULT 499, membership_type text NOT NULL DEFAULT 'individual', referral_numbers text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'pending', admin_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, CONSTRAINT membership_amount CHECK (amount = 499), CONSTRAINT membership_type_check CHECK (membership_type IN ('individual','group')), CONSTRAINT membership_status CHECK (status IN ('pending','approved','rejected')), CONSTRAINT membership_utr CHECK (length(transaction_id) BETWEEN 6 AND 64));
GRANT SELECT, INSERT ON public.membership_payments TO authenticated;
GRANT ALL ON public.membership_payments TO service_role;
ALTER TABLE public.membership_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_read ON public.membership_payments FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY payments_submit ON public.membership_payments FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND status='pending' AND admin_note='' AND reviewed_at IS NULL);
CREATE OR REPLACE FUNCTION public.review_membership(_id uuid, _approve boolean, _note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.membership_payments; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only'; END IF; SELECT * INTO p FROM public.membership_payments WHERE id=_id FOR UPDATE; IF NOT FOUND OR p.status<>'pending' THEN RAISE EXCEPTION 'No pending payment'; END IF; IF p.membership_type='group' AND _approve THEN RAISE EXCEPTION 'Group price and duration require confirmation'; END IF; UPDATE public.membership_payments SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END, admin_note=left(_note,500), reviewed_at=now() WHERE id=_id; IF _approve THEN UPDATE public.profiles SET is_prime=true WHERE id=p.user_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_membership(uuid,boolean,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_membership(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_show_contact() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce((SELECT is_prime FROM public.profiles WHERE id=new.user_id),false) THEN new.show_contact:=false; END IF; IF NOT new.show_contact THEN new.contact_phone:=NULL; new.public_photo:=''; new.public_brand:=''; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.guard_profile_public() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT new.is_prime THEN new.show_public:=false; END IF; RETURN new; END $$;
CREATE TRIGGER profiles_public_guard BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_public();
CREATE OR REPLACE FUNCTION public.posts_match_area(a public.posts,b public.posts) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT a.module=b.module AND a.user_id<>b.user_id AND a.service_type=b.service_type AND b.kind=CASE a.kind WHEN 'seeker' THEN 'employer' WHEN 'employer' THEN 'seeker' WHEN 'owner' THEN 'business' ELSE 'owner' END AND a.status='active' AND b.status='active' AND CASE WHEN a.module='vehicle' THEN lower(trim(a.from_place))=lower(trim(b.from_place)) AND lower(trim(a.to_place))=lower(trim(b.to_place)) AND a.trip_date=b.trip_date ELSE ((a.area_scope='country' OR b.area_scope='country') OR ( (a.area_scope='state' OR b.area_scope='state') AND a.state<>'' AND lower(trim(a.state))=lower(trim(b.state))) OR ((a.area_scope='district' OR b.area_scope='district') AND a.district<>'' AND lower(trim(a.district))=lower(trim(b.district)) AND a.state<>'' AND lower(trim(a.state))=lower(trim(b.state))) OR (a.area_scope='local' AND b.area_scope='local' AND trim(coalesce(a.location,''))<>'' AND lower(trim(a.location))=lower(trim(b.location)))) END $$;
CREATE OR REPLACE FUNCTION public.match_post() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m record; BEGIN FOR m IN SELECT p.* FROM public.posts p WHERE public.posts_match_area(new,p) LOOP IF public.can_notify(new.user_id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(new.user_id,new.id,m.id,'మ్యాచ్ దొరికింది! Match found: '||m.title); END IF; IF public.can_notify(m.user_id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,new.id,'మ్యాచ్ దొరికింది! Match found: '||new.title); END IF; END LOOP; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.notify_matches(_post_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.posts; m record; n integer:=0; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'login required'; END IF; SELECT * INTO j FROM public.posts WHERE id=_post_id AND status='active'; IF NOT FOUND THEN RETURN 0; END IF; FOR m IN SELECT DISTINCT ON(p.user_id) p.* FROM public.posts p WHERE public.posts_match_area(j,p) AND NOT EXISTS(SELECT 1 FROM public.notifications x WHERE x.user_id=p.user_id AND x.matched_post_id=j.id) LOOP EXIT WHEN n>=3; IF public.can_notify(m.user_id) THEN INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(m.user_id,m.id,j.id,'గంట కొట్టారు! Matching need: '||j.title); n:=n+1; END IF; END LOOP; RETURN n; END $$;